package com.security.demo.controller; import com.security.demo.util.JwtUtil; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api") public class UserController { @Autowired JwtUtil jwtUtil; @GetMapping("/public/hello") public String publicHello(){ return "Hello World - Public!";} @GetMapping("/user/hello") public String userHello(){ return "Hello User - Authenticated!";} @GetMapping("/admin/hello") public String adminHello(){ return "Hello Admin - Restricted!";} @PostMapping("/login") public String login(@RequestParam String username,@RequestParam String password){ if(username.equals("demo")&&password.equals("password")) return jwtUtil.generateToken(username); throw new RuntimeException("Invalid credentials"); }}